INSERT INTO public.foundation_sections (id, title, subtitle, description, color, icon, sort_order, is_locked, is_visible, is_published)
VALUES
  ('f1000000-0000-4000-8000-000000000000', 'المهارات الأولى', 'المستوى 0', 'اللبنات الأساسية للغة العربية: الحروف وأشكالها ومخارجها، الحركات والشدة والتنوين والمدود، اللام الشمسية والقمرية والهمزات.', '#17413f', 'sparkles', 1, false, true, true),
  ('f1000000-0000-4000-8000-000000000001', 'أساسيات الكلام والجملة', 'المستوى 1', 'بناء الجملة وأركانها: أقسام الكلمة، المفرد والمثنى والجمع، الضمائر والمعارف، وأركان الجملتين الاسمية والفعلية وأسس الإعراب.', '#0d47a1', 'landmark', 2, false, true, true),
  ('f1000000-0000-4000-8000-000000000002', 'النحو التطبيقي', 'المستوى 2', 'إعراب وتطبيق متقدم: علامات الإعراب الفرعية، صور الخبر والفاعل، النواسخ والتوابع، والحال والتمييز.', '#2f7772', 'library', 3, false, true, true),
  ('f1000000-0000-4000-8000-000000000003', 'النحو المتقدم', 'المستوى 3', 'المفاعيل الخمسة، أساليب الاستثناء والنداء والشرط، العدد، الممنوع من الصرف، إعراب المضارع، والجمل التي لها محل.', '#6a1b9a', 'target', 4, false, true, true),
  ('f1000000-0000-4000-8000-000000000004', 'الصرف', 'المستوى 4', 'بنية الكلمة وميزانها: الميزان الصرفي، المجرد والمزيد، الصحيح والمعتل، المشتقات، المصادر، والإعلال والإبدال.', '#8a508f', 'package', 5, false, true, true),
  ('f1000000-0000-4000-8000-000000000005', 'الإملاء', 'المستوى 5', 'قواعد الرسم الإملائي الصحيح: الهمزات المتوسطة والمتطرفة، الألف اللينة، الحروف التي تُكتب ولا تُلفظ، وعلامات الترقيم.', '#a85d3d', 'award', 6, false, true, true),
  ('f1000000-0000-4000-8000-000000000006', 'القراءة والتعبير', 'المستوى 6', 'فنون الفهم والإنتاج الكتابي: الفهم القرائي، التلخيص، كتابة الفقرة والمقال، الرسائل الإخوانية والرسمية، والقصة الإبداعية.', '#b7791f', 'book-open', 7, false, true, true),
  ('f1000000-0000-4000-8000-000000000007', 'البلاغة', 'المستوى 7', 'تذوق جماليات البيان والمعاني والبديع: التشبيه والاستعارة والكناية، الإنشاء والخبر، المحسنات اللفظية والمعنوية، وتحليل النصوص.', '#5d4037', 'sparkles', 8, false, true, true),
  ('f1000000-0000-4000-8000-000000000008', 'العروض', 'المستوى 8', 'موسيقى الشعر وأوزانه: المقاطع والتفعيلات، الكتابة العروضية والتقطيع، والبحور الشعرية الشهيرة والقافية.', '#00695c', 'scroll-text', 9, false, true, true),
  ('f1000000-0000-4000-8000-000000000009', 'الأدب والنصوص', 'المستوى 9', 'رحلة في عصور الأدب وفنونه: دراسة النصوص الشعرية والنثرية، المعلقات، فنون النثر والشعر الحديث، ونماذج تدريبية شاملة.', '#37474f', 'castle', 10, false, true, true);
